# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the debug panel's System tab: where the backend's memory is, what was slow, and what
#          the app holds, to understand it while using it. Two parts:
#            timings  every State event handler is timed (timed, used by state.py's `event`) and so
#                     are a few inner steps (span); the newest MAX_SAMPLES are kept in memory only,
#                     as the debug log's records are (measurements, not results: nothing is reused).
#            report   read on demand, when the tab opens or on Refresh: memory, sessions, timings,
#                     outside calls (from logs.py's records), the state's size, the process.
# Usage: @perf.timed on a handler / `with perf.span("build view")`; report(...) -> PerfView.
# ---------------------------------------------------------------------------
from __future__ import annotations

import contextlib
import datetime as dt
import functools
import gc
import inspect
import os
import platform
import statistics
import sys
import threading
import time
import types
from collections import deque
from dataclasses import dataclass, field
from importlib import metadata
from pathlib import Path
from typing import TYPE_CHECKING, Any

import polars as pl
from pydantic import BaseModel

if TYPE_CHECKING:
    from collections.abc import Callable, Iterator

# ~100 bytes a sample: bounded however long the backend runs
MAX_SAMPLES = 5000
# rows per table
TOP_ROWS = 12
# a handler or step slower than this feels slow: its numbers are marked
SLOW_MS = 300
SESSION_CHARS = 8  # as logs.session_id
# state vars smaller than this (flags, short texts) are left out of "State held for this tab"
MIN_STATE_BYTES = 100

Row = dict[str, str]

_STARTED = time.time()
_samples: deque[tuple[float, str, float, str]] = deque(maxlen=MAX_SAMPLES)
"""(when, name, ms, session): a State event handler's whole run, or an inner step (name 'step: ...')."""
_lock = threading.Lock()


# -- timings: recording ---------------------------------------------------------------


def record(name: str, ms: float, session: str = "") -> None:
    with _lock:
        _samples.append((time.time(), name, ms, session))


@contextlib.contextmanager
def span(name: str, session: str = "") -> Iterator[None]:
    """Time an inner step, eg building a view; shown as 'step: <name>'."""
    start = time.perf_counter()
    try:
        yield
    finally:
        record(f"step: {name}", (time.perf_counter() - start) * 1000, session)


def _handler_name(fn: Callable[..., Any], kwargs: dict[str, Any]) -> str:
    """A handler's name; one that takes an `action` (State.view_event, every view's one handler)
    is split by it, eg 'view_event: sort'."""
    action = kwargs.get("action")
    return f"{fn.__name__}: {action}" if isinstance(action, str) else fn.__name__


def _session_of(state: Any) -> str:
    try:
        return str(state.router.session.client_token)[:SESSION_CHARS]
    except Exception:  # noqa: BLE001  # a timing without its session is still a timing
        return ""


def timed(fn: Callable[..., Any]) -> Callable[..., Any]:
    """Time a State event handler's whole run, from the event arriving to its last update (for
    one that yields: the waits in between included, eg a fetch). The wrapper is the same kind of
    function as the handler (plain, generator, async, async generator), since Reflex runs each
    kind its own way."""

    def done(state: Any, kwargs: dict[str, Any], start: float) -> None:
        record(_handler_name(fn, kwargs), (time.perf_counter() - start) * 1000, _session_of(state))

    if inspect.isasyncgenfunction(fn):

        @functools.wraps(fn)
        async def async_steps(self: Any, *args: Any, **kwargs: Any) -> Any:
            start = time.perf_counter()
            try:
                async for update in fn(self, *args, **kwargs):
                    yield update
            finally:
                done(self, kwargs, start)

        return async_steps
    if inspect.iscoroutinefunction(fn):

        @functools.wraps(fn)
        async def async_call(self: Any, *args: Any, **kwargs: Any) -> Any:
            start = time.perf_counter()
            try:
                return await fn(self, *args, **kwargs)
            finally:
                done(self, kwargs, start)

        return async_call
    if inspect.isgeneratorfunction(fn):

        @functools.wraps(fn)
        def steps(self: Any, *args: Any, **kwargs: Any) -> Any:
            start = time.perf_counter()
            try:
                yield from fn(self, *args, **kwargs)
            finally:
                done(self, kwargs, start)

        return steps

    @functools.wraps(fn)
    def call(self: Any, *args: Any, **kwargs: Any) -> Any:
        start = time.perf_counter()
        try:
            return fn(self, *args, **kwargs)
        finally:
            done(self, kwargs, start)

    return call


def clear() -> None:
    with _lock:
        _samples.clear()


# -- text -------------------------------------------------------------------------------


def size_text(n: float) -> str:
    """Bytes, short: 812 B, 14 KB, 3.2 MB, 1.31 GB."""
    kb, mb, gb = 1024, 1024**2, 1024**3
    if n >= gb:
        return f"{n / gb:.2f} GB"
    if n >= mb:
        return f"{n / mb:.1f} MB"
    return f"{n / kb:.0f} KB" if n >= kb else f"{n:.0f} B"


def ms_text(ms: float) -> str:
    """Milliseconds, short: 0.4 ms, 12 ms, 1.8 s."""
    if ms >= 1000:  # noqa: PLR2004  # a second
        return f"{ms / 1000:.1f} s"
    return f"{ms:.0f} ms" if ms >= 10 else f"{ms:.1f} ms"  # noqa: PLR2004  # one decimal below 10 ms


def ago_text(seconds: float) -> str:
    """A time span, short: 12 s, 4 min, 3.2 h, 2.1 d."""
    minute, hour, day = 60, 3600, 86400
    if seconds >= day:
        return f"{seconds / day:.1f} d"
    if seconds >= hour:
        return f"{seconds / hour:.1f} h"
    return f"{seconds / minute:.0f} min" if seconds >= minute else f"{seconds:.0f} s"


def share_text(part: float, whole: float) -> str:
    """A share as a whole percent; '<1%' for something that is there but small."""
    if not whole or not part:
        return ""
    return "<1%" if part / whole < 0.01 else f"{part / whole:.0%}"  # noqa: PLR2004  # one percent


def _slow(ms: float) -> str:
    return "1" if ms >= SLOW_MS else ""


# -- measuring ----------------------------------------------------------------------------


def _status_kb(name: str) -> int:
    """A kB field of /proc/self/status (VmRSS, VmHWM, ...) in bytes; 0 where there is no /proc."""
    with contextlib.suppress(OSError, ValueError, IndexError):
        for line in Path("/proc/self/status").read_text().splitlines():
            if line.startswith(f"{name}:"):
                return int(line.split()[1]) * 1024
    return 0


def rough_size(value: Any) -> int:
    """About how much memory a value holds (cheap; for spotting what is big, not exact): a
    DataFrame's buffers, a model's JSON, a container's items one level down."""
    if isinstance(value, pl.DataFrame | pl.Series):
        return int(value.estimated_size())
    if isinstance(value, BaseModel):
        return len(value.model_dump_json())
    for name in ("df", "frame"):  # eg a SmashDb console holding its result
        inner = getattr(value, name, None)
        if isinstance(inner, pl.DataFrame):
            return int(inner.estimated_size())
    if isinstance(value, dict):
        return sys.getsizeof(value) + sum(sys.getsizeof(k) + sys.getsizeof(v) for k, v in value.items())
    if isinstance(value, list | tuple | set):
        return sys.getsizeof(value) + sum(sys.getsizeof(item) for item in value)
    return sys.getsizeof(value)


def shape_text(value: Any) -> str:
    """A value's shape for people: a table's rows × columns, a container's item count, else ''."""
    if isinstance(value, pl.DataFrame):
        return f"{value.height:,} × {value.width}"
    if isinstance(value, pl.Series | list | tuple | set | dict | str):
        return f"{len(value):,} items"
    return ""


def user_variables(
    namespace: dict[str, Any], skip: tuple[str, ...], show_all: bool = False
) -> list[tuple[str, Any, int]]:
    """(name, value, rough size) of a session's own variables, biggest first: the one rule for
    what counts as the user's (the System tab and the Variables pane, variables.py).

    Never private names (_x) or `skip` (pl, db). Modules, functions and classes only with show_all.
    """
    found = [
        (name, value, rough_size(value))
        for name, value in namespace.items()
        if not name.startswith("_") and name not in skip and (show_all or not _is_plumbing(value))
    ]
    return sorted(found, key=lambda item: -item[2])


def _is_plumbing(value: Any) -> bool:
    """Not data: a module, a class, a function or method (what imports and defs leave behind)."""
    return isinstance(value, type | types.ModuleType) or inspect.isroutine(value)


def _db_size(db: Any) -> tuple[int, int]:
    """(tables, bytes) of a session's SmashDb, read now (each table once; a few ms)."""
    tables = size = 0
    with contextlib.suppress(Exception):  # a db that can't be read just counts as nothing
        for name in db.schema():
            tables += 1
            with contextlib.suppress(Exception):
                size += int(db.sql(f'select * from "{name}"').estimated_size())
    return tables, size


def _messages_size(messages: list[Any]) -> int:
    """About how many bytes the chat's messages hold: their text and tool results."""
    total = 0
    for message in messages:
        for part in getattr(message, "parts", []):
            content = getattr(part, "content", None)
            if content is None:
                content = getattr(part, "args", "")
            total += rough_size(content) if not isinstance(content, str) else len(content)
    return total


def _percentile(values: list[float], share: float) -> float:
    ordered = sorted(values)
    return ordered[min(len(ordered) - 1, int(len(ordered) * share))]


def _version(package: str) -> str:
    try:
        return metadata.version(package)
    except metadata.PackageNotFoundError:
        return "?"


# -- the report -----------------------------------------------------------------------------


@dataclass
class PerfView:
    """What the System tab shows; every table is rows of text, made here."""

    tiles: list[Row] = field(default_factory=list)
    """label, value, sub."""
    memory: list[Row] = field(default_factory=list)
    """what, detail, size, share (of the backend's memory), width (the bar, as a CSS %)."""
    variables: list[Row] = field(default_factory=list)
    """name, type, shape, size: this session's biggest variables."""
    sessions: list[Row] = field(default_factory=list)
    """id, mine, age, idle, variables, size, chat, cost."""
    handlers: list[Row] = field(default_factory=list)
    """name, runs, median, p95, max, total, last, slow."""
    slowest: list[Row] = field(default_factory=list)
    """when, name, took, session."""
    calls: list[Row] = field(default_factory=list)
    """what, runs, median, max, total, errors, slow: outside calls, from the debug log's records."""
    state: list[Row] = field(default_factory=list)
    """name, size, share: what this tab's Reflex state holds (what the server keeps and sends)."""
    process: list[Row] = field(default_factory=list)
    """label, value."""
    note: str = ""
    text: str = ""
    """The whole report as plain text, to copy (eg into a chat with an AI)."""


def _timing_rows(samples: list[tuple[float, str, float, str]], now: float) -> tuple[list[Row], list[Row]]:
    """(per name, the slowest single runs) of the kept timings."""
    by_name: dict[str, list[tuple[float, float]]] = {}
    for when, name, ms, _ in samples:
        by_name.setdefault(name, []).append((when, ms))
    rows = []
    for name, runs in by_name.items():
        took = [ms for _, ms in runs]
        rows.append(
            (
                sum(took),
                {
                    "name": name,
                    "runs": f"{len(took):,}",
                    "median": ms_text(statistics.median(took)),
                    "p95": ms_text(_percentile(took, 0.95)),
                    "max": ms_text(max(took)),
                    "total": ms_text(sum(took)),
                    "last": f"{ago_text(now - max(when for when, _ in runs))} ago",
                    "slow": _slow(_percentile(took, 0.95)),
                },
            )
        )
    handlers = [row for _, row in sorted(rows, key=lambda item: -item[0])[:TOP_ROWS]]
    slowest = [
        {
            "when": dt.datetime.fromtimestamp(when).strftime("%H:%M:%S"),  # noqa: DTZ006  # local time, for reading
            "name": name,
            "took": ms_text(ms),
            "session": session,
            "slow": _slow(ms),
        }
        for when, name, ms, session in sorted(samples, key=lambda sample: -sample[2])[:TOP_ROWS]
    ]
    return handlers, slowest


def _call_rows(records: list[dict[str, Any]]) -> list[Row]:
    """The debug log's outside calls, summed by what was called: kind, source and its operation."""
    groups: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        if not isinstance(record.get("ms"), int | float):
            continue
        what = " · ".join(
            str(part)
            for part in (record.get("kind"), record.get("source"), record.get("op") or record.get("tool"))
            if part
        )
        groups.setdefault(what, []).append(record)
    rows = []
    for what, found in groups.items():
        took = [float(record["ms"]) for record in found]
        errors = sum(1 for record in found if record.get("error"))
        rows.append(
            (
                sum(took),
                {
                    "what": what,
                    "runs": f"{len(took):,}",
                    "median": ms_text(statistics.median(took)),
                    "max": ms_text(max(took)),
                    "total": ms_text(sum(took)),
                    "errors": str(errors) if errors else "",
                    "slow": "",
                },
            )
        )
    return [row for _, row in sorted(rows, key=lambda item: -item[0])[:TOP_ROWS]]


def _memory_rows(parts: list[tuple[str, str, int]], rss: int) -> list[Row]:
    """The parts that can be measured, biggest first, then the rest of the backend's memory."""
    parts = sorted(parts, key=lambda part: -part[2])
    rest = max(rss - sum(size for _, _, size in parts), 0)
    parts.append(
        ("everything else", "Python itself, polars, Reflex, the libraries, freed memory not yet returned", rest)
    )
    return [
        {
            "what": what,
            "detail": detail,
            "size": size_text(size),
            "share": share_text(size, rss),
            "width": f"{min(size / rss, 1):.1%}" if rss else "0%",
        }
        for what, detail, size in parts
    ]


def report(  # everything the tab shows is read here, in one place
    session: Any,
    token: str,
    sessions: dict[str, Any],
    records: list[dict[str, Any]],
    state_sizes: dict[str, int],
    skip: tuple[str, ...],
) -> PerfView:
    """Read everything the System tab shows, now.

    session / token: this browser tab's. sessions: every session the backend holds, by token.
    records: the debug log's records. state_sizes: this tab's Reflex state vars, in bytes as JSON.
    skip: names in a namespace that aren't the user's (pl, db).
    """
    now = time.time()
    view = PerfView()
    rss, peak = _status_kb("VmRSS"), _status_kb("VmHWM")
    cpu = time.process_time()
    uptime = now - _STARTED
    with _lock:
        samples = list(_samples)

    # -- memory: this session, the others, the logs. Each session is measured once.
    variables = user_variables(session.namespace, skip)
    var_size = sum(size for _, _, size in variables)
    db_tables, db_size = _db_size(session.db)
    chat_size = _messages_size(session.ai_history)
    log_size = sum(rough_size(record) for record in records)
    held: dict[str, tuple[int, int]] = {token: (len(variables), var_size + db_size + chat_size)}
    for other_token, other in sessions.items():
        if other_token != token:
            names = user_variables(other.namespace, skip)
            size = sum(size for _, _, size in names) + _db_size(other.db)[1] + _messages_size(other.ai_history)
            held[other_token] = (len(names), size)
    others = [other_token for other_token in sessions if other_token != token]
    other_size = sum(held[other_token][1] for other_token in others)
    view.memory = _memory_rows(
        [
            ("this session's variables", f"{len(variables)} names (r1, your own, ...)", var_size),
            ("this session's SmashDb", f"{db_tables} tables, loaded for every session", db_size),
            ("this session's chat", f"{len(session.ai_history)} messages kept for the agent", chat_size),
            ("other sessions", f"{len(others)} (a browser tab each; kept until the backend restarts)", other_size),
            ("debug log", f"{len(records):,} records", log_size),
            ("timings", f"{len(samples):,} of {MAX_SAMPLES:,} samples", len(samples) * 100),
        ],
        rss,
    )
    view.variables = [
        {"name": name, "type": type(value).__name__, "shape": shape_text(value), "size": size_text(size)}
        for name, value, size in variables[:TOP_ROWS]
    ]
    for other_token, other in sorted(sessions.items(), key=lambda item: -getattr(item[1], "used", 0)):
        count, size = held.get(other_token, (0, 0))
        view.sessions.append(
            {
                "id": other_token[:SESSION_CHARS],
                "mine": "1" if other_token == token else "",
                "age": ago_text(now - getattr(other, "started", now)),
                "idle": ago_text(now - getattr(other, "used", now)),
                "variables": str(count),
                "size": size_text(size),
                "chat": f"{len(other.ai_history)} messages",
                "cost": f"${other.ai_cost:.4f}" if other.ai_cost else "",
            }
        )

    # -- timings
    view.handlers, view.slowest = _timing_rows(samples, now)
    view.calls = _call_rows(records)

    # -- what this tab's state holds
    total_state = sum(state_sizes.values())
    view.state = [
        {"name": name, "size": size_text(size), "share": share_text(size, total_state)}
        for name, size in sorted(state_sizes.items(), key=lambda item: -item[1])[:TOP_ROWS]
        if size >= MIN_STATE_BYTES
    ]

    # -- the process
    counts = gc.get_count()
    view.process = [
        {"label": "process", "value": f"pid {os.getpid()}, {threading.active_count()} threads"},
        {"label": "open files", "value": str(_open_files())},
        {"label": "polars thread pool", "value": f"{pl.thread_pool_size()} threads"},
        {"label": "Python objects", "value": f"{len(gc.get_objects()):,} tracked; gc generations {counts}"},
        {
            "label": "versions",
            "value": ", ".join(
                [f"Python {platform.python_version()}"]
                + [f"{name} {_version(name)}" for name in ("reflex", "polars", "pydantic-ai")]
            ),
        },
    ]
    slow = sum(1 for _, name, ms, _ in samples if ms >= SLOW_MS and not name.startswith("step: "))
    view.tiles = [
        {"label": "Backend memory", "value": size_text(rss), "sub": f"peak {size_text(peak)}" if peak else ""},
        {"label": "Sessions", "value": str(len(sessions)), "sub": "one per browser tab, never dropped"},
        {
            "label": "Slow handlers",
            "value": str(slow),
            "sub": f"over {SLOW_MS} ms, of {sum(1 for s in samples if not s[1].startswith('step: ')):,} runs",
        },
        {"label": "CPU used", "value": ago_text(cpu), "sub": f"{cpu / uptime:.1%} of the time up" if uptime else ""},
        {
            "label": "Up for",
            "value": ago_text(uptime),
            "sub": "since " + dt.datetime.fromtimestamp(_STARTED).strftime("%b %d %H:%M"),  # noqa: DTZ006  # local time
        },
    ]
    view.note = " ".join(
        [
            "Read when this tab opens and on Refresh, never in the background.",
            "Sizes are rough (a DataFrame's buffers, a model's JSON): good for spotting what is big.",
            f"Timings: the newest {MAX_SAMPLES:,}, every session, since the backend started.",
        ]
    )
    view.text = as_text(view)
    return view


def _open_files() -> int | str:
    try:
        return len(os.listdir("/proc/self/fd"))
    except OSError:
        return "?"


def table_text(title: str, rows: list[Row], columns: tuple[str, ...]) -> list[str]:
    """A table as lines of plain text (for the copied report); nothing when it has no rows."""
    if not rows:
        return []
    lines = [f"## {title}", " | ".join(columns)]
    lines += [" | ".join(row.get(column, "") for column in columns) for row in rows]
    return [*lines, ""]


def as_text(view: PerfView) -> str:
    """The report as plain text, to paste somewhere (an issue, a chat with an AI)."""
    lines = ["# SmashGPT system report", dt.datetime.now().astimezone().isoformat(timespec="seconds"), ""]
    lines += [f"- {tile['label']}: {tile['value']} ({tile['sub']})" for tile in view.tiles] + [""]
    lines += table_text("Memory", view.memory, ("what", "size", "share", "detail"))
    lines += table_text("Biggest variables (this session)", view.variables, ("name", "type", "shape", "size"))
    lines += table_text("Sessions", view.sessions, ("id", "age", "idle", "variables", "size", "chat", "cost"))
    lines += table_text("Handlers and steps", view.handlers, ("name", "runs", "median", "p95", "max", "total", "last"))
    lines += table_text("Slowest runs", view.slowest, ("when", "name", "took", "session"))
    lines += table_text("Outside calls", view.calls, ("what", "runs", "median", "max", "total", "errors"))
    lines += table_text("State held for this tab", view.state, ("name", "size", "share"))
    lines += table_text("Process", view.process, ("label", "value"))
    return "\n".join(lines)
